"use strict";

const exec = require("child_process").exec;
const fs = require("fs");

const common = require("./apply_common");
const syslog = common.syslog();

function flashRW(boot_dev, callback) {
    syslog.debug("flashRW", boot_dev);
    const cmd = "echo 0 > /sys/block/" + boot_dev + "/force_ro";
    exec(cmd, function(error, stdout, stderr) {
        if (error) {
            common.fail(error);
        } else {
            callback();
        }
    });
}

function copyImg(img_file, boot_dev, callback) {
    const cmd = "dd if=" + img_file + " of=/dev/" + boot_dev + " bs=1M";
    exec(cmd, function(error, stdout, stderr) {
        if (error) {
            common.fail(error);
        } else {
            callback();
        }
    });
}

function finishFlash(extract_dir) {
    common.writeWorkState("verify", function() {
        common.cleanScratchDir(extract_dir, function() {
            syslog.info("Reboot and verify...");
            common.reboot(function() { process.exit(0); });
        });
    });
}

function doFlash(to_version, extract_dir) {
    syslog.debug("Flash bootloader");
    const boot_dev = "mmcblk0boot1";
    const img_file = extract_dir + "/u-boot.img";

    common.doScript(extract_dir, "./preinstall", function() {
        fs.access(img_file, fs.R_OK, function(error) {
            if (error) {
                // file nonexistance is not an error
                finishFlash(extract_dir);
            } else {
                flashRW(boot_dev, function() {
                    copyImg(img_file, boot_dev, function() {
                        common.doScript(extract_dir, "./postinstall", function() {
                            finishFlash(extract_dir);
                        });
                    });
                });
            }
        });
    });
}

function doRetry(from_version, filter) {
    syslog.info("Retry bootloader update from %s", from_version);
    common.getAvailableUpdate("bootloader", from_version, filter, 
        function(update, tarball) {
            doInstall(update.toVersion, tarball);
        });
}

function doInstall(to_version, source) {
    syslog.info("Install bootloader", source);
    common.writeWorkState("init", function() {
        const extract_dir = common.extractDir(to_version, "bootloader");
        common.unpackUpdate(extract_dir, source, function(extract_dir) {
            doFlash(to_version, extract_dir);
        });
    });
}

function doVerify() {
    // if we get this far, clearly it worked
    syslog.info("Bootloader verified!");
    common.finalizeInstall();
}

function executeStep(step, work_state, gui) {
    const ws = work_state.current();
    // XXX better estimate
    const apply_time_est = common.bunzip2Estimate(ws.size);
    syslog.debug("Bootloader estimate", apply_time_est);
    const first_background = __dirname + "/Installer1.png";
    const second_background = __dirname + "/Installer1a.png";
    if (step == "verify") {
        gui.setBackground(second_background);
        gui.setPercent(1);
        doVerify();
    } else if (step == "retry") {
        gui.setBackground(second_background);
        gui.setPercent(0);
        gui.incrementTo(1, apply_time_est);
        doRetry(ws.from, ws.filter);
    } else {
        gui.setBackground(first_background);
        gui.setPercent(0);
        gui.incrementTo(1, apply_time_est);
        doInstall(ws.to, ws.source);
    }
}

module.exports = {
    handlesSubsystem: function(subsystem) {
        return subsystem == "bootloader";
    },
    execute: executeStep
}
